p='src/main/frontend/src/app/features/pools/pools.ts'
s=open(p).read()
start=s.index('  protected readonly pools = signal<readonly PoolView[]>([]);')
end=s.index('  protected readonly name = signal(\'\');')
block=s[start:end]
s=s[:start]+'''  private readonly store = inject(PoolStore);
  protected readonly pools = this.store.pools;
  protected readonly shown = this.store.shown;

'''+s[end:]
s=s.replace('''  protected readonly roster = inject(PoolRoster);
  private readonly settings = inject(SettingsStore);
''','''  protected readonly roster = inject(PoolRoster);
